def cite(key, label=None):
    s=SOURCES[key]
    return f'<a href="{escape(s["url"],quote=True)}" rel="noopener noreferrer">{escape(label or s["title"])}</a>'

def rows(items):
    return '<div class="table-wrap" role="region" aria-label="Evidence table" tabindex="0"><table><thead><tr><th>Date / claim</th><th>Record</th><th>What follows</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in row)+'</tr>' for row in items)+'</tbody></table></div>'

PAGES=[]
def page(route,title,desc,body,keys,hook):
    PAGES.append({'route':route,'title':title,'description':desc,'body':body,'sources':keys,'share_text':hook})

page(HUB,'Before the White House: Trump’s 2014–2017 Paper Trail',
 'A dated source guide to Trump’s campaign launch, Moscow negotiations, Epstein’s 2015 emails, Israel policy and the Acosta–DOJ chronology.',
 f'''<p class="lede">Trump’s first successful presidential campaign overlapped with a proposed Moscow property deal, private emails about his relationship with Jeffrey Epstein, and public promises about Israel. The records sit on different evidentiary levels. Putting them on one timeline makes the overlap visible without pretending they prove one coordinated operation.</p>
 <div class="finding"><strong>The central finding:</strong> there is a documented campaign-era business story, a documented third-party media-strategy exchange, and a documented foreign-policy story. The records reviewed here do not establish a common controller, an intelligence operation or a criminal agreement joining all three.</div>
 <h2>Start with the dates, not the theory</h2>
 <p>The starting point is 2014–2015, rather than a vague “before he ran.” A campaign-events chronology places Trump at New Hampshire’s Freedom Summit on <strong>April 12, 2014</strong>. His campaign announced an exploratory committee on <strong>March 18, 2015</strong>. His FEC-filed campaign response dates the presidential announcement to <strong>June 16, 2015</strong> and the statement of candidacy to June 22. These are different milestones: an appearance, an exploratory announcement, a launch and a filing. {cite('nh','Event chronology')} · {cite('explore','Exploratory announcement')} · {cite('fec','FEC-filed response')}.</p>
 <div class="cards">
 <a href="{MOSCOW}"><span>Russia · business and disclosure</span><h2>The Moscow deal continued into the campaign</h2><p>Read the project timeline, Cohen’s false-statements case and Trump’s response.</p></a>
 <a href="{EMAIL}"><span>Epstein · original email page</span><h2>What Epstein and Wolff discussed in December 2015</h2><p>A three-message chain about anticipated CNN questions, with its missing links intact.</p></a>
 <a href="{ISRAEL}"><span>Israel · policy and transition</span><h2>The UN vote where Israel policy met Russia outreach</h2><p>Follow the public promises, Flynn’s signed statement and the actual vote.</p></a>
 <a href="{DOJ}"><span>DOJ · institutional accountability</span><h2>Acosta, Epstein and Trump: three separate decisions</h2><p>The earlier non-prosecution agreement, the Cabinet appointment and the later federal charges.</p></a></div>
 <h2>The campaign-to-government timeline</h2>'''+rows([
 ('2013–2014: Moscow planning',cite('mueller','Volume I, pp. 67–68'),'An earlier Crocus Group project preceded the later Sater–Cohen negotiations. No construction resulted from that earlier plan.'),
 ('June 16, 2015: presidential launch',cite('fec','Campaign response, background'),'Use the launch date when comparing events during the candidacy.'),
 ('Fall 2015–June 2016: later Moscow project',cite('cohen','Cohen information, ¶7(a)'),'The admitted duration extended beyond the January 2016 cutoff Cohen first gave Congress.'),
 ('December 15–16, 2015: CNN-related emails',cite('house','Three-email PDF, p. 3'),'Wolff and Epstein discussed Trump. The displayed chain does not show participation by Trump or his campaign.'),
 ('March 21, 2016: AIPAC speech',cite('aipac','Transcript'),'Trump publicly promised support for Israel, opposition to imposed UN terms and an embassy move.'),
 ('December 22–23, 2016: transition outreach',cite('flynn','Statement of offense, ¶4'),'Flynn asked Russia to oppose or delay a settlements resolution; the request and the outcome are distinct.'),
 ('April 28, 2017: Acosta takes Cabinet office',cite('acosta','DOL appointment record'),'An appointment is documented; a claim of a reward or quid pro quo requires additional evidence.'),
 ('July 8, 2019: new Epstein charges announced',cite('epsteincharge','SDNY announcement'),'A federal prosecution occurred during Trump’s presidency; that fact alone does not assign personal credit or blame for charging decisions.'),
 ('November 12, 2020: OPR findings',cite('opr','DOJ statement'),'The Department reported poor judgment and inadequate victim treatment, while finding no professional misconduct.')
 ])+f'''<h2>What this comparison adds</h2>
 <p>The most useful question is not whether names can be connected. It is what kind of connection each document actually records. A property negotiation creates a potential business interest. An email about a candidate records the sender’s activity. A public speech records a promise. An official appointment records a personnel decision. Converting any one into another requires a new document, not a more dramatic headline.</p>
 <p>That distinction also exposes testable gaps. For Moscow, seek the signed deal documents and contemporaneous communications. For the Epstein exchange, seek evidence that the proposed advice crossed into the campaign. For Israel, compare the requested diplomatic action with the vote and the eventual policy act. For Acosta, examine the nomination and vetting records rather than assuming a motive from chronology.</p>
 <h2>Three checks against an easy narrative</h2>
 <ol><li><strong>Check the strongest contrary finding.</strong> A documented contact or admitted lie is not automatically proof of an election conspiracy. Keep prosecutorial conclusions alongside the contact record.</li><li><strong>Check authorship.</strong> A congressional press release, a defendant’s admission and an Epstein email are not equivalent authorities. Read the underlying page and ask whose knowledge it represents.</li><li><strong>Check missing joins.</strong> Close dates, shared acquaintances and a shared news cycle can justify a question. They cannot supply the missing instruction, payment, receipt or agreement.</li></ol>
 <h2>Research scope and remaining work</h2>
 <p>This is the first release of a historical research series, not an exhaustive Trump dossier or a fresh allegation of criminal conduct. The immediate priority is the launch period and its documented consequences through 2017; later case outcomes are included where necessary to avoid misleading readers.</p>
 <p>Further document work should examine campaign finance and donor disclosures; Bayrock and related litigation; the separate 2013–2014 Moscow proposal; the 2016 Trump Tower meeting and the Senate’s counterintelligence findings; the full Epstein estate correspondence and underlying flight records; and later Israel, Saudi Arabia and Gulf policy. Those are research leads, not findings announced here. This series does not establish that current military events were engineered to divert attention from Epstein.</p>
 <p>Continue with GAH’s existing <a href="/investigations/trump-in-the-epstein-files">Epstein allegation-source review</a>, which keeps disputed and uncorroborated allegations labeled, and the separate <a href="/investigations/barak-epstein-putin-qatar-carbyne">Barak–Epstein–Putin source audit</a>. Those records should not be treated as a proven bridge to Trump merely because they share names or countries.</p>''',
 ['nh','explore','fec','mueller','cohen','house','aipac','flynn','acosta','epsteincharge','opr'],
 'Trump’s campaign-era paper trail: Moscow negotiations, Epstein’s 2015 emails, Israel policy and DOJ decisions. Read the records and the gaps.')

page(MOSCOW,'Trump Was Running for President. The Moscow Project Was Still Alive.',
 'Cohen’s admitted false January cutoff, the 2015 Moscow letter of intent, Trump’s response and what the record establishes about the campaign-era deal.',
 f'''<p class="lede">The decisive Moscow fact is a date correction: the proposed project did not end in January 2016, as Michael Cohen initially told Congress. His later criminal case put the discussions into approximately June 2016. That moved the business pursuit well into Trump’s presidential campaign.</p>
 <p>{cite('cohen','Read the criminal information, paragraphs 4 and 7')} together with {cite('cohenoutcome','DOJ’s guilty-plea and sentencing entry')}. A charging document by itself is an allegation; here the official case record supplies the separate guilty-plea outcome.</p>
 <h2>There were two Moscow efforts, not one continuous deal</h2>
 <p>Mueller’s report separates the <strong>2013–2014 Crocus Group proposal</strong> from the later <strong>2015–2016 I.C. Expert / Cohen / Felix Sater effort</strong>. The earlier project stayed at the planning stage. The later effort produced a Trump-signed letter of intent transmitted in November 2015. The report also reproduces Sater’s November 3 attempt to frame the project as politically useful. Sater’s pitch is evidence of his proposal, not proof that Putin accepted it. {cite('mueller','Volume I, printed pp. 67–71')}.</p>
 <h2>The admitted change in the story</h2>'''+rows([
 ('Cohen’s original account',cite('cohen','¶4, pp. 2–3'),'He told Congress the project ended in January 2016, described limited discussion with Trump and denied recalling a Russian-government response.'),
 ('The corrected account',cite('cohen','¶7(a)–(c), pp. 5–8'),'The project continued into approximately June; Trump was briefed more often than Cohen had said; Cohen received a response from the Kremlin press office and spoke with a member of that office.'),
 ('The legal outcome',cite('cohenoutcome','Cohen case entry'),'Cohen pleaded guilty November 29, 2018 to false statements to Congress; the Moscow-case sentence was two months, concurrent with his separate case.')
 ])+f'''<h2>Why the January-versus-June distinction matters</h2>
 <p>A project ending before the first votes and a project continuing during the primary contest create different disclosure questions. The discrepancy is therefore more than a rounding error in a businessman’s schedule. It changes which campaign statements and political milestones readers should compare with the negotiation record.</p>
 <p>It does not follow that proposing a building was itself a crime, that a completed building existed, or that a prospective Russian business partner controlled the campaign. Those are separate propositions. The strongest version of this story stays with the documented overlap and the proven false statement.</p>
 <h2>Trump’s response belongs next to the accusation</h2>
 <p>On November 29, 2018, Trump told reporters that the project was an opportunity he chose not to pursue, said there would have been nothing wrong with doing it while campaigning, and accused Cohen of lying to reduce his punishment. He emphasized that the project was never completed. These are Trump’s stated defenses, not a reversal of Cohen’s plea. {cite('trumpresponse','Read the opening exchanges in the transcript')}.</p>
 <p>That response addresses completion and legality. Cohen’s case addresses the accuracy of his account to Congress. The two questions cannot be substituted for each other: a project can fail to reach construction and still have been pursued longer than a witness first admitted.</p>
 <h2>The broader Russia finding must stay visible</h2>
 <p>Mueller reported Russian election interference but did <strong>not establish that campaign members conspired or coordinated with the Russian government in its election-interference activities</strong>. That is the report’s stated investigative conclusion, not a finding that every contact was invented. {cite('mueller','Volume I, printed pp. 1–2')}.</p>
 <p>This article concerns the Moscow business chronology. It does not use Cohen’s lie as a shortcut to an unproven election-conspiracy charge against Trump.</p>
 <h2>What would move this story beyond a recap?</h2>
 <ul><li><strong>The actual commercial instrument:</strong> compare the complete signed letter of intent with the report’s description; distinguish indicative terms from binding commitments.</li><li><strong>The communication chain:</strong> identify dates, sender, recipient and confirmed replies, rather than treating an intermediary’s claimed access as actual Kremlin approval.</li><li><strong>The disclosure comparison:</strong> attach the exact contemporaneous public statement before calling it a contradiction; completed investments and active negotiations are not identical categories.</li><li><strong>The missing financial record:</strong> do not assert an undisclosed payment, completed transfer or payoff without the transaction evidence.</li></ul>
 <p>The durable headline is the overlap between campaign and business, supported by a corrected sworn-account record. The next original reporting task is to acquire and compare the underlying exhibits, not inflate the court outcome.</p>''',
 ['mueller','cohen','cohenoutcome','trumpresponse'],
 'The Moscow project did not end in January 2016. Cohen’s admitted correction moved it into June, during Trump’s campaign. Read the court record and Trump’s response.')

page(EMAIL,'The 2015 Emails Where Epstein and Wolff Discussed Trump’s CNN Answer',
 'A close reading of the December 15–16, 2015 Epstein–Wolff email page: the political strategy discussed, publication provenance and absent campaign connection.',
 f'''<p class="lede">In December 2015, Michael Wolff warned Jeffrey Epstein that CNN might ask candidate Donald Trump about their relationship. Epstein asked what an answer could be. Wolff’s reply discussed turning a possible denial into leverage—or helping Trump in a way that might create an obligation. The exchange is striking. Its evidentiary boundary is just as important: the displayed chain is between Wolff and Epstein.</p>
 <div class="finding"><strong>Open the receipt:</strong> {cite('house','PDF page 3, subject “Heads up”')}. The image shows two messages dated December 15 and a reply headed December 16, 2015. This story is about that page, not a claim that all estate records have been authenticated or exhaustively searched.</div>
 <h2>Read the three steps in order</h2>'''+rows([
 ('December 15: Wolff’s warning',cite('house','p. 3, bottom quoted message'),'Wolff says he hears CNN is planning to ask Trump about Epstein, either on air or afterward. That records Wolff’s statement about a possible question; it is not a CNN assignment record.'),
 ('December 15: Epstein’s question',cite('house','p. 3, middle quoted message'),'Epstein asks about formulating an answer for Trump. The question does not establish that Trump requested assistance.'),
 ('December 16: Wolff’s reply',cite('house','p. 3, top message'),'Wolff outlines possible PR and political benefits to Epstein, depending on Trump’s answer and electoral prospects. The page does not show the advice reaching Trump.')
 ])+f'''<h2>The publication trail is part of the story</h2>
 <p>House Oversight Democrats published the three selected email records on November 12, 2025 and linked the redacted PDF. The Republican-led committee separately announced an additional estate-document release that day. Readers should distinguish the document images from the political framing attached to either release. {cite('houserelease','Minority release and selection')} · {cite('housemajority','Majority release notice')}.</p>
 <p>GAH visually examined page 3 rather than relying on the press release’s summary. The PDF’s date and the event date must not be conflated: these are 2015 messages published in 2025, discussed here in 2026. The other two pages contain different years and claims. They cannot silently be inserted into the 2015 sequence.</p>
 <h2>What the exchange establishes</h2>
 <p>The narrow, supported story is that Epstein and a writer were privately discussing the political consequences of Trump being questioned about Epstein during the campaign. That is newsworthy as a record of attempted reputation management and political positioning. Calling the exchange a proposal keeps the description tied to what the page actually contains.</p>
 <p>The stronger claim—that Trump used this advice—requires evidence of delivery, acknowledgment or a matching instruction. Trump is the subject of the displayed discussion. He is not shown as a sender or recipient. A candidate being discussed in an email is not the same as a candidate participating in it.</p>
 <h2>The White House disputed the release’s framing</h2>
 <p>On the release date, White House press secretary Karoline Leavitt accused Democrats of selectively releasing emails to create a false narrative and smear Trump, Reuters reported. That response is material and belongs beside the documents. It does not, by itself, authenticate or disprove the displayed exchange. {cite('whresponse','Contemporaneous White House response')}.</p>
 <h2>Four things this page cannot prove</h2>
 <ul><li>That CNN actually asked the anticipated question, or that Wolff accurately knew its plans.</li><li>That Trump received, accepted or even knew of the proposal.</li><li>That Epstein successfully exercised leverage or obtained a benefit.</li><li>That the exchange proves an underlying trafficking offense by Trump.</li></ul>
 <p>The word “leverage” describes the strategic possibility raised by the correspondence. It is not used here as a finding of completed blackmail, extortion or an intelligence relationship.</p>
 <h2>The next receipts to seek</h2>
 <p>A stronger follow-up would place the complete surrounding email thread beside the exact CNN interview and any contemporaneous campaign response. Headers and production context matter: who retained the message, whether a quoted chain is complete, whether attachments exist, and whether other messages record actual delivery.</p>
 <p>The House PDF is the acquisition starting point. GAH has not obtained a native mailbox export for this exchange or independently authenticated its transport headers. That limitation does not erase the published document; it states what kind of evidence readers are seeing.</p>
 <p>For allegations elsewhere in the archive, use the separate <a href="/investigations/trump-in-the-epstein-files">Trump–Epstein allegation review</a>. Its disputed and uncorroborated claims retain those classifications. They are not corroborated by being placed next to this different email.</p>''',
 ['house','houserelease','housemajority','whresponse'],
 'December 2015: Epstein and Wolff discussed Trump’s possible CNN answer. The released email shows the proposal—not Trump receiving or approving it. Read page 3.')

page(ISRAEL,'The UN Vote Where Trump’s Israel Policy Met His Russia Outreach',
 'From the postponed 2015 Israel visit to AIPAC promises and Flynn’s December 2016 request to Russia: a policy chronology with the pardon and vote outcome.',
 f'''<p class="lede">There is a documented point where Trump’s Israel policy and his team’s Russia outreach meet: the December 2016 fight over a UN Security Council resolution on Israeli settlements. The record is specific—a requested vote, a foreign ambassador and a signed statement of offense. It does not establish an Epstein connection.</p>
 <h2>2015: the proposed visit did not happen as planned</h2>
 <p>On December 10, 2015, Trump announced that he was postponing a planned Israel visit and Netanyahu meeting. Contemporaneous JTA reporting places that announcement after Netanyahu criticized Trump’s proposed prohibition on Muslim entry to the United States. This is a public diplomatic dispute, not evidence of a concealed agreement. {cite('israel2015','Read the contemporaneous report')}.</p>
 <h2>March 2016: compare the public promise</h2>
 <p>At AIPAC on March 21, Trump opposed UN-imposed terms for an Israeli–Palestinian settlement, promised to use a US veto against such efforts, and pledged to move the American embassy to Jerusalem. The transcript establishes what he said. It does not independently validate every factual assertion in the speech. {cite('aipac','Read the remarks, especially the UN and embassy passages')}.</p>
 <p>That public baseline matters. It gives readers something concrete to compare with the transition’s later diplomatic effort. A policy position stated in a public campaign speech should not be relabeled as secret merely because a later discussion involved Russia.</p>
 <h2>December 2016: the signed account of the Russia request</h2>
 <p>Flynn’s December 1, 2017 signed statement of offense says that a very senior transition official directed him on December 22, 2016 to contact foreign governments about the pending settlements resolution. It says he asked the Russian ambassador to vote against or delay the resolution and later falsely described those conversations to the FBI. {cite('flynn','Read paragraph 4(a)–(d), pp. 4–5')}.</p>
 <p>The same account records a December 23 follow-up in which the ambassador said Russia would not vote against it. The source names a direction and a request. Neither guarantees that the requested outcome occurred.</p>
 <h2>Check the outcome against the request</h2>
 <p>The UN’s own record shows that Resolution 2334 passed on December 23, 2016 by <strong>14 votes in favor, with the United States abstaining</strong>. That outcome is a crucial check on any headline claiming Russia delivered the requested result. {cite('un','Official UN meeting record')}.</p>
 <p>Influence claims need both sides of the ledger: what an intermediary sought and what the decision-maker actually did. A documented approach can be significant even when unsuccessful. An unsuccessful request cannot be reported as a completed favor.</p>
 <h2>Do not freeze Flynn’s case at the plea</h2>
 <p>Flynn later contested the prosecution. Trump granted him a full pardon on November 25, 2020; the White House said he should never have been prosecuted. Any account using the 2017 statement must also disclose that later outcome. This article cites a historical signed admission and does not present Flynn as facing an outstanding conviction. {cite('pardon','Read the official pardon announcement and the administration’s defense')}.</p>
 <h2>The policy act that followed</h2>
 <p>On December 6, 2017, Trump formally recognized Jerusalem as Israel’s capital and directed relocation of the US embassy. This was a later presidential act, distinct from both the 2016 promise and the UN-resolution outreach. {cite('jerusalem','Read the proclamation’s operative paragraph')}.</p>
 <p>A useful accountability story compares promise, action and outcome. It can ask whose advice shaped policy and how decisions were made without treating support for Israel as evidence of foreign control. The relevant actors are identifiable officials and institutions; nationality or religion is not an evidentiary substitute.</p>
 <h2>What is still missing for a broader claim?</h2>
 <p>A claim of a hidden quid pro quo would require records of the alleged exchange and intent. A claim tying these events to Epstein would require a direct communication, instruction, payment or other attributable bridge. None is established by the sources reviewed for this article.</p>
 <p>Further reporting should compare native transition correspondence, official call records and the complete legal history. This story does not establish who designed current military policy, why today’s war is occurring, or whether a news event was manufactured as a distraction. Those questions need their own evidence.</p>''',
 ['israel2015','aipac','flynn','un','pardon','jerusalem'],
 'A specific Israel–Russia intersection: Flynn asked Russia to oppose or delay the 2016 settlements resolution. The UN record shows it passed. Read the request and outcome.')

page(DOJ,'Acosta, Epstein and Trump: The Timeline That Prevents a False Shortcut',
 'The earlier Epstein non-prosecution agreement, Trump’s 2017 Acosta appointment, the 2019 federal case and DOJ’s mixed 2020 findings, separated by date and authority.',
 f'''<p class="lede">The prosecutor associated with Epstein’s earlier federal non-prosecution agreement later became Trump’s labor secretary. That is a real institutional connection. The chronology does not, by itself, prove why he was selected or that Trump directed the earlier deal.</p>
 <h2>Three decisions, three different questions</h2>
 <p>First comes the federal investigation resolved through the non-prosecution agreement in the 2006–2008 period. Second comes the 2017 Cabinet appointment. Third comes the new SDNY prosecution announced in 2019. Treating these as one act conceals the actual accountability questions: who had authority, what decision was made, and what record explains it?</p>
 <p>DOJ’s November 12, 2020 statement reports that its Office of Professional Responsibility found <strong>poor judgment</strong> in Acosta’s decision to use the non-prosecution agreement and in failing to ensure victim notification of the state plea hearing. OPR did <strong>not find professional misconduct</strong> by Department attorneys. Both findings must remain in the story. {cite('opr','Read the findings paragraphs')}.</p>
 <h2>2017: the documented appointment</h2>
 <p>The Department of Labor records that Acosta was sworn in on <strong>April 28, 2017</strong>. This establishes the personnel connection between Trump’s administration and the former prosecutor. It does not supply an appointment motive. {cite('acosta','DOL’s dated announcement')}.</p>
 <p>A “reward for protecting Epstein” headline would add an unproven causal claim. To support it, reporting would need nomination correspondence, attributable testimony or another record linking the selection to that purpose. The fact that an appointment followed an earlier decision is insufficient.</p>
 <h2>2019: a new federal prosecution also belongs on the timeline</h2>
 <p>On July 8, 2019, SDNY announced federal sex-trafficking and conspiracy charges against Epstein. The allegations concerned conduct in New York and Florida during 2002–2005. The announcement identifies the prosecutors and describes the charged case; it does not charge Trump as a participant. {cite('epsteincharge','Read the prosecution announcement and indictment link')}.</p>
 <p>Epstein died before that case was tried; the official case-status page records the ensuing dismissal proceedings. Reporting the indictment as a trial conviction would be wrong. {cite('epsteincase','Read the case-status record')}.</p>
 <p>The prosecution occurred during Trump’s first presidency. That is important contrary context to a blanket claim that no federal case was pursued under that administration. It also does not establish that Trump personally ordered or deserved credit for the prosecution. Presidential tenure and an individual charging decision are different levels of responsibility.</p>
 <h2>What the OPR review changes—and what it does not</h2>
 <p>The review supplies a documented institutional criticism. An editor need not invent a covert motive to explain why a flawed resolution and inadequate victim treatment warrant scrutiny. Conversely, the absence of a professional-misconduct finding should not be rewritten as a conclusion that the handling was exemplary.</p>
 <p>For accountability, preserve the distinction between a bad decision, a violation of professional obligations and a provable criminal offense. Each requires its own standard and supporting record. A dramatic headline that collapses them makes the article easier to rebut.</p>
 <h2>Where original reporting should go next</h2>
 <ul><li><strong>Original decision records:</strong> compare the agreement, draft charging material, approval chain and contemporaneous notification correspondence.</li><li><strong>Appointment records:</strong> obtain the nomination and vetting file before assigning a motive to the Cabinet choice.</li><li><strong>Victim notification:</strong> ask what was prepared, delayed, sent and received, with dates and responsible offices.</li><li><strong>Later disclosure decisions:</strong> examine each withholding and release under its actual authority; a flag for review is not automatically proof of suppression.</li></ul>
 <p>GAH’s existing <a href="/investigations/epstein-july-2007-decision-gap">July 2007 decision-gap reconstruction</a>, <a href="/investigations/hold-the-letter">victim-letter investigation</a> and <a href="/investigations/doj-oip-epstein-review-public-figure-flags-2026">DOJ review-email audit</a> provide separate source trails. This article links them as research paths; it does not announce a fresh verification of every underlying exhibit.</p>
 <p>A missing record is a precise reporting target. It is not evidence that Trump directed a withheld decision. Silence can tell a reporter where to ask next; it cannot answer the question.</p>''',
 ['opr','acosta','epsteincharge','epsteincase'],
 'The earlier Epstein deal, Acosta’s 2017 appointment and the 2019 federal prosecution are three separate decisions. Here is the dated DOJ record—and what it cannot prove.')

CSS='''body{margin:0;background:#131b17;color:#eeeae0;font:17px/1.75 system-ui,-apple-system,sans-serif}a{color:#edc88e;text-underline-offset:3px}.wrap{width:min(960px,calc(100% - 36px));margin:auto}main{padding:38px 0 65px}h1{font-size:clamp(32px,5vw,53px);line-height:1.13;max-width:20ch}h2{font-size:26px;line-height:1.25;margin-top:2em}h3{font-size:20px}.lede{font-size:21px;line-height:1.6;color:#e1e4d9}.eyebrow{color:#e5bf83;font-size:12px;text-transform:uppercase;letter-spacing:.12em}.byline,.small{font-size:14px;color:#bdc8bd}.finding{background:#203127;padding:19px 22px;border-left:4px solid #d3b178;margin:25px 0}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,270px),1fr));gap:16px;margin:26px 0}.cards>a{border:1px solid #576951;padding:20px;text-decoration:none;border-radius:9px;background:#1b2820}.cards span{font-size:12px;text-transform:uppercase;letter-spacing:.08em}.cards h2{font-size:25px;margin-top:.5em}.cards p{color:#e2e2d5;font-size:16px}.table-wrap{overflow-x:auto;max-width:100%;margin:25px 0}table{border-collapse:collapse;width:100%;font-size:15px;min-width:570px}td,th{text-align:left;vertical-align:top;padding:13px 12px;border-bottom:1px solid #4f604b}th{color:#edc88e}li{margin:12px 0}.source-list li{padding-bottom:13px;border-bottom:1px solid #3a493a}.source-list p{margin:.4em 0}.related{border-top:1px solid #63765b;margin-top:35px;padding-top:12px}.share{display:inline-block;background:#dbc395;color:#172319;border-radius:6px;padding:9px 16px;font-weight:750;text-decoration:none}.skip-link{position:absolute;left:-9999px}.skip-link:focus{left:10px;top:10px;background:#fff;color:#111;z-index:9999}.article-footer{border-top:1px solid #52634c;padding:20px 0 30px}@media(max-width:600px){main{padding-top:25px}.lede{font-size:19px}h2{font-size:24px}}'''

def render(p):
    schema={'@context':'https://schema.org','@type':'Article','headline':p['title'],'description':p['description'],'datePublished':DATE,'dateModified':DATE,'mainEntityOfPage':BASE+p['route'],'url':BASE+p['route'],'author':{'@type':'Organization','name':'Grok Archive Hub Editorial Desk','url':BASE+'/about-the-operator#editorial-responsibility'},'publisher':{'@type':'NewsMediaOrganization','name':'Grok Archive Hub'},'isAccessibleForFree':True,'citation':[SOURCES[k]['url'] for k in p['sources']]}
    sourcehtml=''.join(f'<li id="source-{k}">{cite(k)}<p class="small"><strong>Type:</strong> {escape(SOURCES[k]["kind"])}. <strong>Locate:</strong> {escape(SOURCES[k]["locator"])}.</p><p class="small">{escape(SOURCES[k]["limit"])}</p></li>' for k in p['sources'])
    share='https://twitter.com/intent/tweet?'+urlencode({'text':p['share_text'],'url':BASE+p['route']+'?utm_source=x&utm_medium=social&utm_campaign=trump_records_2015'})
    related=' · '.join(f'<a href="{q["route"]}">{escape(q["title"])}</a>' for q in PAGES if q['route']!=p['route'])
    return f'''<!doctype html><html lang="en" data-gah-shell="v3"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{escape(p['title'])} | Grok Archive Hub</title><meta name="description" content="{escape(p['description'],quote=True)}"><link rel="canonical" href="{BASE+p['route']}"><meta name="robots" content="index,follow"><meta name="gah-indexability-policy" content="index,follow"><meta name="gah-ad-eligible" content="false"><meta name="gah-ad-status" content="AD-EXCLUDE"><meta name="gah-ad-zone" content="none"><meta name="gah-adsense-approved" content="false">
<meta property="og:type" content="article"><meta property="og:title" content="{escape(p['title'],quote=True)}"><meta property="og:description" content="{escape(p['description'],quote=True)}"><meta property="og:url" content="{BASE+p['route']}"><meta property="og:site_name" content="Grok Archive Hub"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="{escape(p['title'],quote=True)}"><meta name="twitter:description" content="{escape(p['description'],quote=True)}"><meta property="article:published_time" content="{DATE}">
<style>{CSS}</style><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False,separators=(',',':')).replace('<',chr(92)+'u003c')}</script></head><body><a class="skip skip-link" href="#main">Skip to content</a><header class="site-header"><nav class="wrap" aria-label="Primary"><a href="/">Grok Archive Hub</a> · <a href="/investigations">Investigations</a> · <a href="/latest">Latest</a> · <a href="/search">Search</a></nav></header><main id="main" class="wrap"><article><p class="eyebrow">Campaign records · Historical source analysis · October 22, 2026</p><h1>{escape(p['title'])}</h1><p class="byline"><a rel="author" href="/about-the-operator#editorial-responsibility">Grok Archive Hub Editorial Desk</a> · Published <time datetime="{DATE}">October 22, 2026</time></p><p><a href="{HUB}">The Trump campaign-records series</a> · <a href="#sources">Inspect the sources</a></p>{p['body']}<h2 id="sources">Source notes and how to verify</h2><ol class="source-list">{sourcehtml}</ol><p class="small">Method: selected official records, transcripts and identified contemporaneous reporting were compared by date, author, authority and outcome. This is AI-assisted historical source analysis. No new witness interviews were conducted; this is not a complete search of every Trump, Epstein or Russia record. Government publication does not make every embedded assertion true. See <a href="/methodology">methodology</a>, <a href="/editorial-policy">editorial policy</a> and <a href="/corrections">corrections</a>.</p><p><a class="share" href="{escape(share,quote=True)}" target="_blank" rel="noopener noreferrer">Share this source check on X</a></p><section class="related"><h2>Keep following the documents</h2><p>{related}</p><p><a href="/evidence-data/trump-campaign-records-20261022/source-manifest.json">Source manifest and acquisition hashes</a> · <a href="/newsletter">Follow GAH updates</a></p></section></article></main><footer class="article-footer"><div class="wrap"><a href="/privacy">Privacy</a> · <a href="/corrections">Corrections</a> · <a href="/about-the-operator">Editorial responsibility</a></div></footer></body></html>'''

for p in PAGES:
    target=ROOT/(p['route'].lstrip('/')+'.html')
    target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(render(p))

manifest={'schema':'gah.trump-campaign-records.v1','review_date':DATE,'scope':'Selected 2014–2017 events; later legal outcomes retained. First release, not an exhaustive dossier.','methods':['Read selected Mueller Volume I sections and Cohen criminal information text','Visually inspected House email PDF page 3','Read Flynn statement of offense and checked later pardon','Compared official case outcomes, appointment record, UN outcome and presidential proclamation','Read both congressional release notices and contemporaneous White House response'],'sources':SOURCES,'articles':[{k:v for k,v in p.items() if k!='body'} for p in PAGES],'not_established':['One coordinated Epstein–Russia–Israel operation involving Trump','Trump received or approved the Epstein–Wolff proposed advice','Trump directed the earlier Epstein non-prosecution agreement or selected Acosta as a reward','A completed Trump Moscow project or a proven election-interference agreement inferred from the project','Current military events were manufactured to distract from Epstein']}
data=ROOT/'evidence-data/trump-campaign-records-20261022';data.mkdir(parents=True,exist_ok=True)
(data/'source-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')

# Explicit routes prevent NAS fallback from serving stale or unrelated content.
worker=ROOT/'_worker.js';s=worker.read_text()
for marker,addition in [
 ('const FRONTDOOR_PATHS = new Set([\n',''.join(f'  "{p["route"]}",\n' for p in PAGES)),
 ('const FRONTDOOR_ROUTE_ASSETS = new Map([\n',''.join(f'  ["{p["route"]}", "{p["route"]}.html"],\n' for p in PAGES)),
 ('const CORE_SITEMAP_ENTRIES = [\n',''.join(f'  ["{BASE+p["route"]}", "{DATE}"],\n' for p in PAGES)),
 ('const AD_EXCLUDED_EXACT_PATHS = new Map([\n',''.join(f'  ["{p["route"]}", "public-records-historical-analysis-ad-free"],\n' for p in PAGES))]:
    assert marker in s,marker
    if addition not in s:s=s.replace(marker,marker+addition,1)
worker.write_text(s)

feature=f'''<section class="wrap" aria-labelledby="trump-records-2015" style="padding:22px;margin:22px auto;background:#203127;border:1px solid #bfa473;border-radius:9px"><p class="eyebrow">New historical source series · October 22, 2026</p><h2 id="trump-records-2015"><a href="{HUB}">Before the White House: Trump’s 2014–2017 Paper Trail</a></h2><p>Start with the campaign launch, then follow the Moscow project, Epstein’s December 2015 emails, the Israel–Russia UN vote and the Acosta–DOJ chronology. Five linked articles distinguish records, denials, legal outcomes and missing evidence.</p><p><a href="{MOSCOW}">The Moscow deal</a> · <a href="{EMAIL}">The Epstein–Wolff emails</a> · <a href="{ISRAEL}">Israel and the UN vote</a> · <a href="{DOJ}">Acosta and DOJ</a></p></section>'''
for f in ['index.html','latest.html','investigations.html']:
    p=ROOT/f;s=p.read_text();assert '<main' in s,f
    if 'id="trump-records-2015"' not in s:
        end=s.index('>',s.index('<main'))+1;s=s[:end]+feature+s[end:]
    p.write_text(s)
print(json.dumps({'built':len(PAGES),'routes':[p['route'] for p in PAGES],'sources':len(SOURCES),'promoted_on':['/','/latest','/investigations']}))
